-- Seed: course go-foundations
-- Generated by content/tools/build-seed.mjs from content/courses/go-foundations. Do not edit by hand.
-- Idempotent: safe to run again after editing the content files.

BEGIN;

DO $$
DECLARE
    t text;
    seq text;
BEGIN
    FOREACH t IN ARRAY ARRAY['catalog.course', 'course.module', 'course.lesson', 'challenge.challenges', 'challenge.questions',
                             'challenge.question_options', 'challenge.challenge_test_cases', 'challenge.coding_files', 'storage.assets'] LOOP
        seq := pg_get_serial_sequence(t, 'id');
        IF seq IS NOT NULL THEN
            EXECUTE format('SELECT setval(%L, GREATEST((SELECT COALESCE(max(id), 0) FROM %s), (SELECT last_value FROM %s)))', seq, t, seq);
        END IF;
    END LOOP;
END $$;

INSERT INTO catalog.course (public_id, title, concept, description, image, level, duration, instructor, cost, point_price, reward, language_id, category_id, access_model, publish_status, is_hidden, is_deleted)
VALUES ('go-foundations', 'Go Fundamentals: Types, Errors, Slices & Maps', 'Learn Go the way it is used for services and tooling: zero values, slices and the append aliasing bug, maps and structs, interfaces, errors as values, generics and go test.', 'Learn Go the way it is used for services and tooling: zero values, slices and the append aliasing bug, maps and structs, interfaces, errors as values, generics and go test. 8 lessons, each starting from a real bug or incident, with beginner-friendly challenges.', NULL, 'beginner'::level_enum, 160, 'CodeDev Engineering Team', 0, 0, 50,
        (SELECT id FROM catalog.language WHERE name = 'Go'),
        (SELECT id FROM catalog.category WHERE name = 'Go Development'),
        'free', 'draft', true, false)
ON CONFLICT (public_id) DO UPDATE SET
    title = EXCLUDED.title, concept = EXCLUDED.concept, description = EXCLUDED.description, image = EXCLUDED.image,
    level = EXCLUDED.level, duration = EXCLUDED.duration, instructor = EXCLUDED.instructor, cost = EXCLUDED.cost,
    point_price = EXCLUDED.point_price, reward = EXCLUDED.reward, language_id = EXCLUDED.language_id,
    category_id = EXCLUDED.category_id, access_model = EXCLUDED.access_model, updated_at = now();

DO $$ BEGIN
    IF (SELECT count(*) FROM catalog.career_role WHERE code = ANY(ARRAY['student', 'backend_developer', 'devops_engineer']::text[])) <> 3 THEN
        RAISE EXCEPTION 'course go-foundations: unknown code in careerRoles';
    END IF;
END $$;
DELETE FROM catalog.course_career_role WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations');
INSERT INTO catalog.course_career_role (course_id, career_role_id) SELECT (SELECT id FROM catalog.course WHERE public_id = 'go-foundations'), id FROM catalog.career_role WHERE code = ANY(ARRAY['student', 'backend_developer', 'devops_engineer']::text[]);
DO $$ BEGIN
    IF (SELECT count(*) FROM catalog.learning_goal WHERE code = ANY(ARRAY['fundamentals', 'first_job']::text[])) <> 2 THEN
        RAISE EXCEPTION 'course go-foundations: unknown code in goals';
    END IF;
END $$;
DELETE FROM catalog.course_learning_goal WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations');
INSERT INTO catalog.course_learning_goal (course_id, learning_goal_id) SELECT (SELECT id FROM catalog.course WHERE public_id = 'go-foundations'), id FROM catalog.learning_goal WHERE code = ANY(ARRAY['fundamentals', 'first_job']::text[]);
DO $$ BEGIN
    IF (SELECT count(*) FROM catalog.skill WHERE code = ANY(ARRAY['data_structures', 'testing', 'api_design']::text[])) <> 3 THEN
        RAISE EXCEPTION 'course go-foundations: unknown code in skills';
    END IF;
END $$;
DELETE FROM catalog.course_skill WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations');
INSERT INTO catalog.course_skill (course_id, skill_id, weight)
SELECT (SELECT id FROM catalog.course WHERE public_id = 'go-foundations'), s.id, v.weight
FROM (VALUES ('data_structures', 2), ('testing', 2), ('api_design', 1)) AS v(code, weight)
JOIN catalog.skill s ON s.code = v.code;

-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'go-foundations') AND h.status <> 'completed');

COMMIT;
